actions.script:
$liteState = Join-Path $env:ProgramData 'LiteOS'
if (-not (Test-Path -LiteralPath $liteState)) { New-Item -ItemType Directory -Path $liteState -Force | Out-Null }
$ifBase = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces'
$stateFile = Join-Path $liteState 'prev-nagle.txt'
$valueNames = @('TcpAckFrequency', 'TCPNoDelay')
# state lines: <interface GUID>|<TcpAckFrequency or ->|<TCPNoDelay or -> ; '-' = value did not exist
$known = @{}
$lines = New-Object System.Collections.ArrayList
if (Test-Path -LiteralPath $stateFile) {
    foreach ($line in @(Get-Content -LiteralPath $stateFile)) {
        $f = ([string]$line).Split('|')
        if ($f.Count -eq 3) { $known[$f[0]] = $true; [void]$lines.Add([string]$line) }
    }
}
$keys = @(Get-ChildItem -LiteralPath $ifBase)
$pending = 0
foreach ($k in $keys) {
    foreach ($n in $valueNames) {
        $v = $k.GetValue($n, $null)
        if ($null -eq $v -or [string]$v -ne '1') { $pending++ }
    }
}
if ($pending -eq 0) {
    Write-Output ('UNCHANGED: TcpAckFrequency=1 and TCPNoDelay=1 are already set on all ' + $keys.Count + ' network interface(s).')
    return
}
foreach ($k in $keys) {
    if (-not $known.ContainsKey($k.PSChildName)) {
        $rec = $k.PSChildName
        foreach ($n in $valueNames) {
            $v = $k.GetValue($n, $null)
            if ($null -eq $v) { $rec += '|-' } else { $rec += ('|' + [string]$v) }
        }
        [void]$lines.Add($rec)
    }
}
Set-Content -LiteralPath $stateFile -Value @($lines) -Encoding ASCII
foreach ($k in $keys) {
    $p = $ifBase + '\' + $k.PSChildName
    foreach ($n in $valueNames) { New-ItemProperty -LiteralPath $p -Name $n -PropertyType DWord -Value 1 -Force | Out-Null }
}
Write-Output ('LiteOS: TcpAckFrequency=1 and TCPNoDelay=1 set on ' + $keys.Count + ' network interface(s); restart to apply.')

actions.undo:
$liteState = Join-Path $env:ProgramData 'LiteOS'
if (-not (Test-Path -LiteralPath $liteState)) { New-Item -ItemType Directory -Path $liteState -Force | Out-Null }
$ifBase = 'HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces'
$stateFile = Join-Path $liteState 'prev-nagle.txt'
$valueNames = @('TcpAckFrequency', 'TCPNoDelay')
if (Test-Path -LiteralPath $stateFile) {
    foreach ($line in @(Get-Content -LiteralPath $stateFile)) {
        $f = ([string]$line).Split('|')
        if ($f.Count -ne 3) { continue }
        $p = $ifBase + '\' + $f[0]
        if (-not (Test-Path -LiteralPath $p)) { continue }
        for ($i = 0; $i -lt 2; $i++) {
            $n = $valueNames[$i]
            $prev = $f[$i + 1]
            if ($prev -eq '-') {
                if ($null -ne (Get-Item -LiteralPath $p).GetValue($n, $null)) { Remove-ItemProperty -LiteralPath $p -Name $n }
            } else {
                New-ItemProperty -LiteralPath $p -Name $n -PropertyType DWord -Value ([int]$prev) -Force | Out-Null
            }
        }
    }
    Remove-Item -LiteralPath $stateFile -Force
    Write-Output 'LiteOS: TCP ACK / Nagle settings restored; restart to apply.'
} else {
    # no state file = this revert already ran (or the tweak changed nothing); values that equal 1
    # may be your own settings, so nothing is removed
    Write-Output 'LiteOS: no saved TCP ACK / Nagle state - nothing to revert.'
}
